from itertools import combinations
import random

def check_girth(edges, n, min_girth=6):
    """Check if the graph has girth at least min_girth."""
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: 0}
        queue = [(start, -1, 0)]  # (current, parent, distance)
        while queue:
            curr, parent, dist = queue.pop(0)
            for neighbor in adj[curr]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    # Found a cycle
                    cycle_len = dist + visited[neighbor] + 1
                    if cycle_len < min_girth:
                        return False
                else:
                    visited[neighbor] = dist + 1
                    queue.append((neighbor, curr, dist + 1))
    return True

def check_degrees(edges, n, min_deg=2, max_deg=5):
    """Check if all vertices have degree between min_deg and max_deg."""
    deg = [0] * n
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
    return all(min_deg <= d <= max_deg for d in deg)

